+
+bool ShenandoahTerminatorTerminator::can_work() const {
+  // Can work if the thread cannot be cancelled (i.e., STW worker) or the thread is not being held in reserve.
+  return !_cancellable || WorkerThread::worker_id() < _heap->control_thread()->concurrent_worker_count();
+}
+
+// Return true means: withdraw offer to terminate, go back and look for work.
+bool ShenandoahTerminatorTerminator::should_exit_termination() {
+  return _heap->cancelled_gc();
+}
+
+ShenandoahTaskTerminator::DelayContext::DelayContext() {
+  _yield_count = 0;
+  reset_hard_spin_information();
+}
+
+void ShenandoahTaskTerminator::DelayContext::reset_hard_spin_information() {
+  _hard_spin_count = 0;
+  _hard_spin_limit = WorkStealingHardSpins >> WorkStealingSpinToYieldRatio;
+}
+
+bool ShenandoahTaskTerminator::DelayContext::needs_sleep() const {
+  return _yield_count >= WorkStealingYieldsBeforeSleep;
+}
+
+void ShenandoahTaskTerminator::DelayContext::do_step() {
+  assert(_yield_count < WorkStealingYieldsBeforeSleep, "Number of yields too large");
+  // Each spin iteration is counted as a yield for purposes of
+  // deciding when to sleep.
+  _yield_count++;
+  // Periodically yield instead of spinning after WorkStealingSpinToYieldRatio
+  // spins.
+  if (_hard_spin_count > WorkStealingSpinToYieldRatio) {
+    os::naked_yield();
+    reset_hard_spin_information();
+  } else {
+    // Hard spin this time
+    for (uint j = 0; j < _hard_spin_limit; j++) {
+      SpinPause();
+    }
+    _hard_spin_count++;
+    // Increase the hard spinning period but only up to a limit.
+    _hard_spin_limit = MIN2(2 * _hard_spin_limit,
+                            (uint) WorkStealingHardSpins);
+  }
+}
+
+ShenandoahTaskTerminator::ShenandoahTaskTerminator(uint n_threads, TaskQueueSetSuper* queue_set) :
+  _n_threads(n_threads),
+  _queue_set(queue_set),
+  _offered_termination(0),
+  _blocker(Mutex::nosafepoint, "ShenandoahTaskTerminator_lock"),
+  _spin_master(nullptr) { }
+
+ShenandoahTaskTerminator::~ShenandoahTaskTerminator() {
+  if (_offered_termination != 0) {
+    assert(_offered_termination == _n_threads, "Must be terminated or aborted");
+  }
+
+  assert(_spin_master == nullptr, "Should have been reset");
+}
+
+#ifdef ASSERT
+void ShenandoahTaskTerminator::assert_queue_set_empty() const {
+  _queue_set->assert_empty();
+}
+#endif
+
+void ShenandoahTaskTerminator::reset_for_reuse() {
+  if (_offered_termination != 0) {
+    assert(_offered_termination == _n_threads,
+           "Only %u of %u threads offered termination", _offered_termination, _n_threads);
+    assert(_spin_master == nullptr, "Leftover spin master " PTR_FORMAT, p2i(_spin_master));
+    _offered_termination = 0;
+  }
+}
+
+void ShenandoahTaskTerminator::reset_for_reuse(uint n_threads) {
+  reset_for_reuse();
+  _n_threads = n_threads;
+}
+
+void ShenandoahTaskTerminator::notify_all() {
+  MonitorLocker locker(&_blocker, Mutex::_no_safepoint_check_flag);
+  locker.notify_all();
+}
+
+bool ShenandoahTaskTerminator::exit_termination(size_t tasks, ShenandoahTerminatorTerminator* terminator) {
+  return tasks > 0 || (terminator != nullptr && terminator->should_exit_termination());
+}
+
+size_t ShenandoahTaskTerminator::tasks_in_queue_set() const {
+  return _queue_set->tasks();
+}
+
+void ShenandoahTaskTerminator::prepare_for_return(Thread* this_thread, size_t tasks) {
+  assert(_blocker.is_locked(), "must be");
+  assert(_blocker.owned_by_self(), "must be");
+  assert(_offered_termination >= 1, "must be");
+
+  if (_spin_master == this_thread) {
+    _spin_master = nullptr;
+  }
+
+  if (tasks >= _offered_termination - 1) {
+    _blocker.notify_all();
+  } else {
+    for (; tasks > 1; tasks--) {
+      _blocker.notify();
+    }
+  }
+}
+
+static bool can_work(ShenandoahTerminatorTerminator* terminator) {
+  return terminator == nullptr || terminator->can_work();
+}
+
+bool ShenandoahTaskTerminator::wait_while_ineligible(MonitorLocker* x, ShenandoahTerminatorTerminator* terminator) {
+  assert(_blocker.owned_by_self(), "Must hold _blocker here");
+  while (!can_work(terminator) && !exit_termination(0, terminator)) {
+    x->wait();
+
+    if (_offered_termination == _n_threads) {
+      // all threads terminated
+      return true;
+    }
+
+    if (exit_termination(0, terminator)) {
+      // termination offer withdrawn (cancelled)
+      break;
+    }
+  }
+
+  return false;
+}
+
+bool ShenandoahTaskTerminator::offer_termination(ShenandoahTerminatorTerminator* terminator) {
+  assert(_n_threads > 0, "Initialization is incorrect");
+  assert(_offered_termination < _n_threads, "Invariant");
+
+  // Single worker, done
+  if (_n_threads == 1) {
+    _offered_termination = 1;
+    assert_queue_set_empty();
+    return true;
+  }
+
+  Thread* the_thread = Thread::current();
+
+  MonitorLocker x(&_blocker, Mutex::_no_safepoint_check_flag);
+  _offered_termination++;
+
+  if (_offered_termination == _n_threads) {
+    prepare_for_return(the_thread);
+    assert_queue_set_empty();
+    return true;
+  }
+
+  if (!can_work(terminator)) {
+    if (wait_while_ineligible(&x, terminator)) {
+      // This thread was not admitted
+      prepare_for_return(the_thread);
+      assert_queue_set_empty();
+      return true;
+    }
+
+    // This thread was admitted and can work (or the tasks were cancelled).
+    prepare_for_return(the_thread, 0);
+    _offered_termination--;
+    return false;
+  }
+
+  for (;;) {
+    if (_spin_master == nullptr) {
+      _spin_master = the_thread;
+      DelayContext delay_context;
+
+      while (!delay_context.needs_sleep()) {
+        size_t tasks;
+        bool should_exit_termination;
+        {
+          MutexUnlocker y(&_blocker, Mutex::_no_safepoint_check_flag);
+          delay_context.do_step();
+          // Intentionally read the number of tasks outside the mutex since this
+          // is potentially a long operation making the locked section long.
+          tasks = tasks_in_queue_set();
+          should_exit_termination = exit_termination(tasks, terminator);
+        }
+        // Immediately check exit conditions after re-acquiring the lock.
+        if (_offered_termination == _n_threads) {
+          prepare_for_return(the_thread);
+          assert_queue_set_empty();
+          return true;
+        } else if (should_exit_termination) {
+          prepare_for_return(the_thread, tasks);
+          _offered_termination--;
+          return false;
+        }
+      }
+      // Give up spin master before sleeping.
+      _spin_master = nullptr;
+    }
+    bool timed_out = x.wait(WorkStealingSleepMillis);
+
+    // Immediately check exit conditions after re-acquiring the lock.
+    if (_offered_termination == _n_threads) {
+      prepare_for_return(the_thread);
+      assert_queue_set_empty();
+      return true;
+    } else if (!timed_out) {
+      // We were woken up. Don't bother waking up more tasks.
+      prepare_for_return(the_thread, 0);
+      _offered_termination--;
+      return false;
+    } else {
+      size_t tasks = tasks_in_queue_set();
+      if (exit_termination(tasks, terminator)) {
+        prepare_for_return(the_thread, tasks);
+        _offered_termination--;
+        return false;
+      }
+    }
+  }
+}

